package com.storemate.backend.web;
import com.storemate.backend.domain.*;import com.storemate.backend.repo.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Transactional class RemainingWorkflowIntegrationTest {
 @Autowired AccountRepository accounts;@Autowired StoreRepository stores;@Autowired StoreMemberRepository members;@Autowired WorkSessionRepository sessions;@Autowired WorkShiftRepository shifts;@Autowired AttendancePolicyRepository policies;@Autowired Notifier notifier;@Autowired PayrollController payroll;@Autowired HandoverController handovers;@Autowired HandoverContextService context;
 @Autowired WorkTimeCorrectionController timeCorrections;@Autowired WorkTimeCorrectionRepository timeHistory;
 Account owner,worker,previous;Store store;StoreMember member,previousMember;
 @BeforeEach void setup(){String key=UUID.randomUUID().toString().substring(0,8);owner=accounts.save(new Account("ow-"+key,"test",Role.OWNER,"사장","20000101"));worker=accounts.save(new Account("wk-"+key,"test",Role.STAFF,"직원","20000101"));previous=accounts.save(new Account("pr-"+key,"test",Role.STAFF,"직전 직원","20000101"));store=stores.save(new Store("테스트","기타",null,null,null,"09:00","22:00",key,owner));members.save(new StoreMember(owner,store,Role.OWNER,MemberStatus.APPROVED));member=members.save(new StoreMember(worker,store,Role.STAFF,MemberStatus.APPROVED));previousMember=members.save(new StoreMember(previous,store,Role.STAFF,MemberStatus.APPROVED));}
 private WorkSession work(Account a,LocalDateTime in,LocalDateTime out,Integer wage)throws Exception{var w=new WorkSession(a,store);var field=WorkSession.class.getDeclaredField("clockIn");field.setAccessible(true);field.set(w,in);if(wage!=null)w.assignWage(wage,"SNAPSHOT",owner);if(out!=null)w.correctMissingClockOut(out,owner,"테스트");return sessions.save(w);}
 @Test void payrollSeparatesBaseAllowanceDeductionAndDeduplicatesRetry()throws Exception{
  var ym=YearMonth.now().minusMonths(1);work(worker,ym.atDay(2).atTime(9,0),ym.atDay(2).atTime(11,0),12000);
  var add=new PayrollController.Add("OVERTIME","확인한 가산분",3000L,null,null,null,"payroll-test-key-01");payroll.add(owner,store.getId(),member.getId(),ym.toString(),add);payroll.add(owner,store.getId(),member.getId(),ym.toString(),add);
  var result=payroll.add(owner,store.getId(),member.getId(),ym.toString(),new PayrollController.Add("DEDUCTION","확인한 공제",1000L,null,null,null,"payroll-test-key-02"));assertEquals(24000,result.basePay());assertEquals(3000,result.additions());assertEquals(1000,result.deductions());assertEquals(26000,result.netPay());assertEquals(2,result.entries().size());
  var finalized=payroll.finalizePay(owner,store.getId(),member.getId(),ym.toString(),new PayrollController.Finalize(true,true,true));assertTrue(finalized.finalized());assertEquals(26000,payroll.mine(worker,store.getId(),ym.toString()).netPay());assertThrows(ApiException.class,()->payroll.add(owner,store.getId(),member.getId(),ym.toString(),add));
 }
 @Test void unresolvedHistoricalWageBlocksFinalStatement()throws Exception{var ym=YearMonth.now().minusMonths(1);work(worker,ym.atDay(2).atTime(9,0),ym.atDay(2).atTime(10,0),null);assertThrows(ApiException.class,()->payroll.finalizePay(owner,store.getId(),member.getId(),ym.toString(),new PayrollController.Finalize(true,true,true)));}
 @Test void workerCannotAddOwnPayAndNegativeDeductionCannotOverflow(){assertThrows(ApiException.class,()->payroll.add(worker,store.getId(),member.getId(),YearMonth.now().toString(),new PayrollController.Add("OTHER","사유",1L,null,null,null,"payroll-test-key-03")));assertThrows(ApiException.class,()->payroll.add(owner,store.getId(),member.getId(),YearMonth.now().toString(),new PayrollController.Add("DEDUCTION","사유",Long.MIN_VALUE,null,null,null,"payroll-test-key-04")));}
 @Test void directWageCorrectionPreservesOriginalSnapshotAndReason()throws Exception{var ym=YearMonth.now().minusMonths(1);var work=work(worker,ym.atDay(3).atTime(9,0),ym.atDay(3).atTime(10,0),12000);var value=payroll.add(owner,store.getId(),member.getId(),ym.toString(),new PayrollController.Add("WAGE_CORRECTION","11/3 실제 시급 정정 차액",1000L,null,null,null,"payroll-test-key-05"));assertEquals(12000,work.getHourlyWage());assertEquals(13000,value.netPay());assertEquals("11/3 실제 시급 정정 차액",value.entries().getFirst().reason());}
 @Test void previousHandoverUsesActualShiftAndSnapshotsPart()throws Exception{
  var now=LocalDateTime.now().withNano(0);previousMember.setWorkPart("마감 파트");work(previous,now.minusHours(4),now.minusHours(1),12000);var memo=handovers.create(previous,store.getId(),new Dto.HandoverRequest("직전 근무 메모",false));work(worker,now.minusMinutes(30),null,12000);
  var result=handovers.previous(worker,store.getId());assertEquals("직전 직원",result.author());assertEquals("마감 파트",result.workPart());assertEquals(memo.id(),result.items().getFirst().id());
 }
 @Test void closedTimeCorrectionKeepsWageAndAuditsBeforeAndAfter()throws Exception{var day=LocalDate.now().minusDays(1);var w=work(worker,day.atTime(9,0),day.atTime(10,0),12000);timeCorrections.correct(owner,store.getId(),member.getId(),w.getId(),new WorkTimeCorrectionController.Request(day.atTime(11,0).toString(),day.atTime(10,0).toString(),"직원과 실제 퇴근 시각 확인"));assertEquals(day.atTime(11,0),w.getClockOut());assertEquals(12000,w.getHourlyWage());var history=timeHistory.findBySessionOrderByIdAsc(w);assertEquals(1,history.size());assertEquals(day.atTime(10,0),history.getFirst().getBeforeTime());assertThrows(ApiException.class,()->timeCorrections.correct(owner,store.getId(),member.getId(),w.getId(),new WorkTimeCorrectionController.Request(day.atTime(12,0).toString(),day.atTime(10,0).toString(),"이전 화면")));}
 @Test void missingClockOutAlertsWithoutFabricatingClockOut()throws Exception{var w=work(worker,LocalDateTime.now().minusHours(20),null,12000);new AttendanceAutomation(sessions,members,shifts,policies,notifier).scan();assertTrue(w.isMissingAlertSent());assertNull(w.getClockOut());assertEquals(12000,w.getHourlyWage());}
 @Test void automaticClockOutRequiresExplicitPolicyAndValidSchedule()throws Exception{var day=LocalDate.now().minusDays(2);var w=work(worker,day.atTime(22,0),null,12000);shifts.save(new WorkShift(member,day,"22:00","06:00"));var p=new AttendancePolicy(store.getId());p.update(16,60,true);policies.save(p);new AttendanceAutomation(sessions,members,shifts,policies,notifier).scan();assertEquals(day.plusDays(1).atTime(6,0),w.getClockOut());assertTrue(w.getClockOutCorrectionReason().startsWith("자동 처리:"));}
}
